using EEMS.Modules.Results.Domain;using Microsoft.EntityFrameworkCore;namespace EEMS.Modules.Results.Infrastructure;
public sealed class ResultsDbContext(DbContextOptions<ResultsDbContext> o):DbContext(o){public DbSet<SubmissionState> States=>Set<SubmissionState>();public DbSet<ResultSubmission> Submissions=>Set<ResultSubmission>();public DbSet<ResultDetail> Details=>Set<ResultDetail>();public DbSet<ResultDocument> Documents=>Set<ResultDocument>();public DbSet<ResultVerification> Verifications=>Set<ResultVerification>();public DbSet<ResultDispute> Disputes=>Set<ResultDispute>();public DbSet<OfficialResult> OfficialResults=>Set<OfficialResult>();
#pragma warning disable CA1725
protected override void OnModelCreating(ModelBuilder b){b.HasDefaultSchema("results");var s=b.Entity<SubmissionState>();s.ToTable("submission_states");s.HasKey(x=>x.Id);s.Property(x=>x.Id).HasColumnName("submission_state_id").ValueGeneratedNever();s.Property(x=>x.Code).HasColumnName("code").HasMaxLength(40);s.Property(x=>x.Name).HasColumnName("name").HasMaxLength(100);s.Property(x=>x.IsVerified).HasColumnName("is_verified");s.Property(x=>x.IsActive).HasColumnName("is_active");s.HasIndex(x=>x.Code).IsUnique();
var x=b.Entity<ResultSubmission>();x.ToTable("submissions");x.HasKey(a=>a.Id);x.Property(a=>a.Id).HasColumnName("submission_id");x.Property(a=>a.TenantId).HasColumnName("tenant_id");x.Property(a=>a.ElectionId).HasColumnName("election_id");x.Property(a=>a.ElectionCenterId).HasColumnName("election_center_id");x.Property(a=>a.PositionId).HasColumnName("position_id");x.Property(a=>a.SubmittedByUserId).HasColumnName("submitted_by_user_id");x.Property(a=>a.StateId).HasColumnName("submission_state_id");x.Property(a=>a.IdempotencyKey).HasColumnName("idempotency_key").HasMaxLength(100);x.Property(a=>a.DeclaredTotalVotes).HasColumnName("declared_total_votes");x.Property(a=>a.CreatedAtUtc).HasColumnName("created_at");x.Property(a=>a.Version).HasColumnName("version").IsConcurrencyToken();x.HasOne<SubmissionState>().WithMany().HasForeignKey(a=>a.StateId).OnDelete(DeleteBehavior.Restrict);x.HasIndex(a=>new{a.TenantId,a.Id}).IsUnique();x.HasIndex(a=>new{a.TenantId,a.IdempotencyKey}).IsUnique();x.HasIndex(a=>new{a.TenantId,a.ElectionId,a.ElectionCenterId,a.PositionId}).IsUnique();
var d=b.Entity<ResultDetail>();d.ToTable("details");d.HasKey(a=>new{a.TenantId,a.SubmissionId,a.CandidateElectionId});d.Property(a=>a.TenantId).HasColumnName("tenant_id");d.Property(a=>a.SubmissionId).HasColumnName("submission_id");d.Property(a=>a.CandidateElectionId).HasColumnName("candidate_election_id");d.Property(a=>a.Votes).HasColumnName("votes");Map<ResultDocument>(b,"documents","result_document_id");Map<ResultVerification>(b,"verifications","verification_id");Map<ResultDispute>(b,"disputes","dispute_id");
var o=b.Entity<OfficialResult>();o.ToTable("official_results");o.HasKey(a=>a.Id);o.Property(a=>a.Id).HasColumnName("official_result_id");o.Property(a=>a.TenantId).HasColumnName("tenant_id");o.Property(a=>a.ElectionId).HasColumnName("election_id");o.Property(a=>a.PositionId).HasColumnName("position_id");o.Property(a=>a.CandidateElectionId).HasColumnName("candidate_election_id");o.Property(a=>a.Votes).HasColumnName("votes");o.Property(a=>a.AuthoritySource).HasColumnName("authority_source").HasMaxLength(300);o.Property(a=>a.PublishedByUserId).HasColumnName("published_by_user_id");o.Property(a=>a.PublishedAtUtc).HasColumnName("published_at");o.HasIndex(a=>new{a.TenantId,a.ElectionId,a.PositionId,a.CandidateElectionId}).IsUnique();}
private static void Map<T>(ModelBuilder b,string table,string key)where T:class{var e=b.Entity<T>();e.ToTable(table);e.HasKey("Id");e.Property<Guid>("Id").HasColumnName(key);e.Property<Guid>("TenantId").HasColumnName("tenant_id");e.Property<Guid>("SubmissionId").HasColumnName("submission_id");}}
